using System;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
namespace Underwater.Editor {
public static class NaturalFishMotionAudit {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Output="Renders/NaturalFishMotion/";
 public static void Apply(){var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);var ids=new System.Collections.Generic.List<string>();int count=0;Physics.SyncTransforms();foreach(var l in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None)){var b=l.GetComponent<ReefSphereBody>();if(!b||l.kind=="Coral"||l.kind=="Fire coral"||l.kind=="Ray tail")continue;var old=l.transform.position;l.GetComponent<ReefAnimalClearance>()?.Enforce();if(!b.Clear(l.transform.position)){if(!b.PlaceNear(l.transform.position)||Vector3.Distance(old,l.transform.position)>2)throw new Exception("Unsafe saved fish placement: "+l.name);}if(old!=l.transform.position){ids.Add(GlobalObjectId.GetGlobalObjectIdSlow(l.transform).targetObjectId.ToString());Debug.Log("FISH_START_CLEARANCE "+l.kind+" "+old+" -> "+l.transform.position);}}foreach(var life in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None)){if(!new[]{"Dolphin","Reef shark","Manta","Turtle"}.Contains(life.kind))continue;var animation=life.GetComponentInChildren<Animation>();if(!animation||!animation.clip)throw new Exception("Missing featured swim clip: "+life.kind);var motion=animation.GetComponent<ReefImportedAnimation>();if(!motion)motion=animation.gameObject.AddComponent<ReefImportedAnimation>();motion.distanceClock=true;motion.travelActor=life.transform;motion.referenceTravelSpeed=life.kind=="Dolphin"?.7f:life.kind=="Reef shark"?.75f:life.kind=="Manta"?.42f:.2f;motion.minimumTravelRate=life.kind=="Dolphin"||life.kind=="Reef shark"?.12f:.18f;EditorUtility.SetDirty(motion);ids.Add(GlobalObjectId.GetGlobalObjectIdSlow(motion).targetObjectId.ToString());var gid=GlobalObjectId.GetGlobalObjectIdSlow(animation);if(gid.targetPrefabId!=0)ids.Add(gid.targetPrefabId.ToString());count++;}foreach(var motion in UnityEngine.Object.FindObjectsByType<FishBodyMotion>(FindObjectsSortMode.None))if(motion.GetComponent<GrouperStroke>()){motion.enabled=false;EditorUtility.SetDirty(motion);ids.Add(GlobalObjectId.GetGlobalObjectIdSlow(motion).targetObjectId.ToString());}EditorSceneManager.SaveScene(scene);File.WriteAllLines(Output+"ModifiedIds.txt",ids);Debug.Log("NATURAL_FISH_ADAPTERS_INSTALLED="+count);Run();}
 static void Require(bool test,string message){if(!test)throw new Exception(message);}
 static void Load(){EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();}
 static void Visuals(SeaLife life,float dt){foreach(var driver in life.GetComponentsInChildren<ReefImportedAnimation>())if(driver.distanceClock)driver.StepPlayback(dt);var sharkFlex=life.GetComponentInChildren<SharkBodyMotion>();if(sharkFlex)sharkFlex.Step(dt);var shader=life.GetComponent<FishBodyMotion>();if(shader&&shader.enabled)shader.Step(dt);var grouper=life.GetComponent<GrouperStroke>();if(grouper)grouper.Step(dt);var lion=life.GetComponent<LionfishTravelAnimation>();if(lion)lion.StepVisual(dt);var moray=life.GetComponentInChildren<YellowMorayMotion>();if(moray)moray.Step(dt);}
 public static void Run(){RunAudit(true);}
 public static void MovementOnly(){RunAudit(false);}
 static void RunAudit(bool includeHazards){
  Directory.CreateDirectory(Output);var report=new System.Text.StringBuilder();Load();var schools=UnityEngine.Object.FindObjectsByType<FishSchool>(FindObjectsSortMode.None);foreach(var s in schools)s.Initialize();var agents=schools.SelectMany(s=>s.fish).Distinct().ToArray();var starts=agents.Select(a=>a.transform.position).ToArray();var distances=new float[agents.Length];var stalls=new float[agents.Length];float maxTurn=0,maxStep=0,worstStall=0;const float dt=1f/30;int penetrations=0,backwards=0;
  for(int frame=0;frame<1800;frame++){var before=agents.Select(a=>a.transform.position).ToArray();var heading=agents.Select(a=>a.transform.forward).ToArray();foreach(var school in schools)school.Simulate(dt);for(int i=0;i<agents.Length;i++){var a=agents[i];var delta=a.transform.position-before[i];float moved=delta.magnitude;distances[i]+=moved;stalls[i]=moved<.002f*dt?stalls[i]+dt:0;worstStall=Mathf.Max(worstStall,stalls[i]);if(!a.GetComponent<ReefSphereBody>().Clear(a.transform.position))penetrations++;if(moved>.00001f&&!a.Escaping&&Vector3.Dot(delta.normalized,a.transform.forward)<-.1f)backwards++;maxTurn=Mathf.Max(maxTurn,Vector3.Angle(heading[i],a.transform.forward)/dt);maxStep=Mathf.Max(maxStep,moved);}}
  report.AppendLine("Schooling fish="+agents.Length+" schools="+schools.Length+" seconds=60 maxTurn="+maxTurn+" maxStep="+maxStep+" longestStationary="+worstStall+" penetrations="+penetrations+" backwards="+backwards+" minTravel="+distances.Min());foreach(var a in agents.Select((fish,i)=>new {fish,i}).Where(x=>stalls[x.i]>8))report.AppendLine("SCHOOL_STALL "+a.fish.name+" at="+a.fish.transform.position+" stationary="+stalls[a.i]+" travel="+distances[a.i]);Require(penetrations==0&&backwards==0&&maxTurn<75&&maxStep<.09f,"Schooling movement/collision regression");Require(distances.All(d=>d>.1f),"A schooling fish never moved");
  File.WriteAllText(Output+"Validation.txt",report.ToString());Load();var featured=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(l=>!l.GetComponent<FishAgent>()&&new[]{"Dolphin","Reef shark","Manta","Stingray","Turtle","Anglerfish","Grouper","Lumen","Lionfish","Moray","Butterflyfish","Flame angelfish"}.Contains(l.kind)).ToArray();foreach(var life in featured){var body=life.GetComponent<ReefSphereBody>();float travel=0,turn=0,stationary=0,worst=0;var cruise=life.GetComponent<ReefCruiser>();var wreck=life.GetComponent<WreckCreature>();var shark=life.GetComponent<OpenWaterShark>();var manta=life.GetComponent<MarineSwimmer>();var ray=life.GetComponent<StingraySwimmer>();var turtle=life.GetComponent<TurtleSwimmer>();var follower=life.GetComponent<ReefFishFollower>();var encounter=life.GetComponent<ReefEncounter>();foreach(var a in life.GetComponentsInChildren<ReefImportedAnimation>())if(a.distanceClock)a.InitializePlayback();
   for(int frame=0;frame<1800;frame++){var p=life.transform.position;var heading=life.transform.forward;if(cruise)cruise.Step(dt);else if(wreck)wreck.Step(dt,frame==300?(Vector3?)(p+Vector3.forward*.3f):null,frame==300?(Vector3?)p:null);else if(shark)shark.Step(dt,OceanWorld.Centers[6],Vector3.zero,false);else if(manta)manta.Step(dt);else if(ray)ray.Step(dt);else if(turtle)turtle.Step(dt);else if(follower)follower.Step(dt,frame<900?(Vector3?)(OceanWorld.Centers[3]+new Vector3(frame*dt*.15f,1.6f,0)):null,Vector3.forward);else if(encounter)encounter.Step(dt,p-life.transform.forward*.3f,frame==300?.3f:10);Visuals(life,dt);life.GetComponent<ReefAnimalClearance>()?.Enforce();Physics.SyncTransforms();float moved=Vector3.Distance(p,life.transform.position);travel+=moved;turn=Mathf.Max(turn,Vector3.Angle(heading,life.transform.forward)/dt);stationary=moved<.002f*dt?stationary+dt:0;worst=Mathf.Max(worst,stationary);Require(!body||body.Clear(life.transform.position),"Featured fish penetrated reef: "+life.name);Require(moved<.12f,"Featured fish teleported: "+life.name+" frame="+frame+" delta="+(life.transform.position-p)+" heading="+life.transform.forward);}
   report.AppendLine(life.kind+" | "+life.name+" seconds=60 travel="+travel+" maxTurn="+turn+" longestStationary="+worst);File.WriteAllText(Output+"Validation.txt",report.ToString());Require(travel>.05f||life.kind=="Moray","Featured fish stuck: "+life.name);
   foreach(var driver in life.GetComponentsInChildren<ReefImportedAnimation>())if(driver.distanceClock){for(int f=0;f<120;f++)driver.StepPlayback(dt);float rest=driver.CurrentRate;for(int f=0;f<90;f++){life.transform.position+=life.transform.forward*driver.referenceTravelSpeed*dt;driver.StepPlayback(dt);}float swim=driver.CurrentRate;Require(swim>rest*2,"Imported stroke does not follow travel: "+life.kind);report.AppendLine("  playback rest="+rest+" swim="+swim);}
  }
  Load();var drivers=UnityEngine.Object.FindObjectsByType<ReefImportedAnimation>(FindObjectsSortMode.None);foreach(var driver in drivers){var a=driver.GetComponent<Animation>();if(!a||!a.clip)continue;var bones=a.GetComponentsInChildren<Transform>();a.clip.SampleAnimation(a.gameObject,0);var p=bones.Select(t=>t.localPosition).ToArray();var q=bones.Select(t=>t.localRotation).ToArray();a.clip.SampleAnimation(a.gameObject,a.clip.length);float pos=0,angle=0;for(int i=0;i<bones.Length;i++){pos=Mathf.Max(pos,Vector3.Distance(p[i],bones[i].localPosition));angle=Mathf.Max(angle,Quaternion.Angle(q[i],bones[i].localRotation));}report.AppendLine("Clip="+a.clip.name+" duration="+a.clip.length+" loopPosition="+pos+" loopDegrees="+angle);Require(pos<.025f&&angle<5,"Imported clip seam: "+a.clip.name);}
  if(includeHazards){Load();SharkDolphinReview.Inspect();Load();ReducedLionfishIntegration.Validate();}ReefCollisionValidation.Run();File.WriteAllText(Output+"Validation.txt",report.ToString());Debug.Log("NATURAL_FISH_MOTION_VALIDATED agents="+agents.Length+" featured="+featured.Length);}
 public static void ReviewVisuals(){Load();Directory.CreateDirectory(Output);var camera=Camera.main;var optics=camera.GetComponent<ReefOptics>();if(optics)optics.enabled=false;foreach(var kind in new[]{"Dolphin","Reef shark","Manta","Turtle","Lionfish"}){var life=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).First(l=>l.kind==kind);var player=life.GetComponentInChildren<Animation>();var skin=life.GetComponentsInChildren<SkinnedMeshRenderer>().First(r=>r.enabled);for(int phase=0;phase<3;phase++){player.clip.SampleAnimation(player.gameObject,player.clip.length*phase/3);var b=skin.bounds;float distance=Mathf.Max(b.size.x,Mathf.Max(b.size.y,b.size.z))*1.7f;camera.transform.position=b.center+(life.transform.right*.85f+life.transform.forward*.5f+Vector3.up*.25f).normalized*distance;camera.transform.LookAt(b.center);camera.fieldOfView=45;camera.nearClipPlane=.01f;ReefCorrectionAudit.Capture(camera,Output+kind.Replace(" ","")+phase+".png");}}Debug.Log("FISH_VISUAL_PHASES_CAPTURED");}
 public static void Inventory(){EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);var report=new System.Text.StringBuilder();foreach(var life in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(l=>l.kind!="Coral"&&l.kind!="Fire coral"&&l.kind!="Ray tail").OrderBy(l=>l.kind)){var clip=life.GetComponentInChildren<Animation>();report.AppendLine(life.kind+" | "+life.name+" | owners="+string.Join(",",life.GetComponents<MonoBehaviour>().Select(c=>c.GetType().Name))+" | anim="+(clip&&clip.clip?clip.clip.name+" "+clip.clip.length:"shader/procedural")+" | visual="+string.Join(",",life.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&!(r is LineRenderer)).Select(r=>r.sharedMaterial?r.sharedMaterial.shader.name:"MISSING")));}foreach(var school in UnityEngine.Object.FindObjectsByType<FishSchool>(FindObjectsSortMode.None))report.AppendLine("SCHOOL | "+school.name+" fish="+school.GetComponentsInChildren<FishAgent>().Length);File.WriteAllText(Output+"Inventory.txt",report.ToString());Debug.Log("NATURAL_FISH_INVENTORY_SAVED");}
}
}
